    def spiral_y(phi):
        return b * phi * math.sin(phi)

    def spiral_derivative_x(phi):
        return b * (math.cos(phi) - b * math.sin(phi))

    def spiral_derivative_y(phi):
        return b * (math.sin(phi) + b * math.cos(phi))

    def distance_to_spiral(phi, x, y):
        px, py = spiral_x(phi), spiral_y(phi)
        dx, dy = x - px, y - py
        return dx * dx + dy * dy

    def find_phi_for_target():
        # Use a binary search to find the phi at which the distance to the target is minimized
        low, high = 0, 2 * math.pi
        while high - low > 1e-9:
            mid = (low + high) / 2
            if distance_to_spiral(mid, tx, ty) > distance_to_spiral(low, tx, ty):
                high = mid
            else:
                low = mid
        return (low + high) / 2

    target_phi = find_phi_for_target()
    px, py = spiral_x(target_phi), spiral_y(target_phi)
    dx, dy = spiral_derivative_x(target_phi), spiral_derivative_y(target_phi)

    # Find intersection point
    # The line equation is (px, py) + t * (dx, dy)
    # The target point is (tx, ty)
